Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_equals_equal_buffers(void) {
    // Setup: create two buffers with identical data
    const char *test_str = "Hello, World!";
    buffer_t *buf1 = helper_make_buffer_with_data((char *)test_str);
    buffer_t *buf2 = helper_make_buffer_with_data((char *)test_str);

    // Sanity: buffers should not be NULL and should contain the expected data
    TEST_ASSERT_NOT_NULL(buf1);
    TEST_ASSERT_NOT_NULL(buf2);
    helper_assert_buffer_data_equals(buf1, test_str);
    helper_assert_buffer_data_equals(buf2, test_str);

    // Test: call buffer_equals
    int result = buffer_equals(buf1, buf2);

    // Assertions: buffers are equal, so result should be 1
    TEST_ASSERT_EQUAL_INT(1, result);

    // Cleanup
    buffer_free(buf1);
    buffer_free(buf2);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_equals_equal_buffers);
    return UNITY_END();
}

